window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ffa8c68d1caa60ff"]={"versions": [{"id": "FIG-ffa8c68d1caa60ff", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> AUTOSAR-M2-Metamodell (UML-Klassendiagramm).</li>\n<li><strong>Technischer Zweck:</strong> Formale Definition des Mappings von Zeitbeschreibungen (<code>TimingDescription</code>) auf Classic-Platform-Software-Cluster (<code>CpSoftwareCluster</code>) sowie deren Ressourcen (<code>CpSoftwareClusterResource</code>) zur kontraktbasierten Schnittstellendefinition (SLA/Timing-Contracts) zwischen verteilten Entwicklungsparteien (OEM, Tier-1, Tier-2).</li>\n<li><strong>Funktionale Einordnung:</strong> Verankert in <code>AUTOSAR_TPS_TimingExtensions</code> (R20-11, Kap. 4.7.4; Anforderungen <code>RS_TIMEX_00025</code>, <code>TPS_TIMEX_00066</code>). Adressiert modulare, unabhängig updatebare Software-Cluster (SWCL) im Classic AUTOSAR, indem temporale Budgets, Latenzgrenzen und Ausführungsordnungen explizit als Provider- und Requestor-Rollen auf Clusterebene abgebildet werden.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Klassen & Generalisierungen</p>\n<ul class=\"fig-list\">\n<li><strong><code>TDCpSoftwareClusterMappingSet</code></strong> (Spezialisierung von <code>ARElement</code>):</li>\n<li>Top-Level-Container auf ARXML-Paketebene (<code>ARElement</code>), bündelt alle clusterbezogenen Timing-Mappings eines Systems oder Teilsystems.</li>\n<li><strong><code>TDCpSoftwareClusterMapping</code></strong> (Spezialisierung von <code>Identifiable</code>):</li>\n<li>Assoziationsentität zur Verknüpfung einer Timing-Beschreibung mit Software-Clustern unter Berücksichtigung von Provider/Requestor-Rollen.</li>\n<li><strong><code>TDCpSoftwareClusterResourceMapping</code></strong> (Spezialisierung von <code>Identifiable</code>):</li>\n<li>Assoziationsentität zur feingranularen Bindung einer Timing-Beschreibung an eine spezifische Software-Cluster-Ressource.</li>\n<li><strong><code>SoftwareCluster::CpSoftwareCluster</code></strong> (Spezialisierung von <code>ARElement</code>):</li>\n<li>Repräsentiert die funktionale Einheit/Partition eines Classic-Platform-Software-Clusters.</li>\n<li><strong><code>SoftwareCluster::CpSoftwareClusterResource</code></strong> (Spezialisierung von <code>Identifiable</code>):</li>\n<li>Repräsentiert eine konkrete Hardware-/Software-Ressource innerhalb eines Clusters (z. B. Shared Memory, Kommunikationspuffer, Task-/Core-Kapazität).</li>\n<li><strong><code>TimingDescription::TimingDescription</code></strong> (Spezialisierung von <code>Identifiable</code>):</li>\n<li>Generischer Zielcontainer der Timing Extensions für Ereignisse, Ketten (<code>TimingEvent</code>, <code>ExecutionOrderConstraint</code>, <code>LatencyConstraint</code>).</li>\n</ul>\n<p class=\"fig-p\">#### Assoziationen, Kardinalitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>TDCpSoftwareClusterMappingSet</code> ➔ <code>TDCpSoftwareClusterMapping</code>:</strong></li>\n<li>Komposition, Rolle: <code>+tdCpSoftwareClusterToTdMapping</code>, Kardinalität <code>0..*</code>.</li>\n<li>Stereotypen: <code>«atpVariation»</code> (variantenabhängig aktivierbar/konfigurierbar), <code>«atpSplitable»</code> (kann über mehrere ARXML-Dateien/Autorenfragmente verteilt deklariert werden).</li>\n<li><strong><code>TDCpSoftwareClusterMappingSet</code> ➔ <code>TDCpSoftwareClusterResourceMapping</code>:</strong></li>\n<li>Komposition, Rolle: <code>+tdCpSoftwareClusterResourceToTdMapping</code>, Kardinalität <code>0..*</code>.</li>\n<li>Stereotypen: <code>«atpVariation»</code>, <code>«atpSplitable»</code>.</li>\n<li><strong><code>TDCpSoftwareClusterMapping</code> ➔ <code>CpSoftwareCluster</code>:</strong></li>\n<li>Rolle <code>+provider</code>: Unidirektionale Referenz, Kardinalität <code>0..1</code> (Cluster, der das Zeitverhalten/die Dienstgüte garantiert).</li>\n<li>Rolle <code>+requestor</code>: Unidirektionale Referenz, Kardinalität <code>0..*</code> (Cluster, die diese Timing-Anforderung stellen bzw. konsumieren).</li>\n<li><strong><code>TDCpSoftwareClusterMapping</code> ➔ <code>TimingDescription</code>:</strong></li>\n<li>Rolle <code>+timingDescription</code>: Unidirektionale Referenz, Kardinalität <code>0..1</code>.</li>\n<li><strong><code>TDCpSoftwareClusterResourceMapping</code> ➔ <code>CpSoftwareClusterResource</code>:</strong></li>\n<li>Rolle <code>+resource</code>: Unidirektionale Referenz, Kardinalität <code>0..1</code>.</li>\n<li><strong><code>TDCpSoftwareClusterResourceMapping</code> ➔ <code>TimingDescription</code>:</strong></li>\n<li>Rolle <code>+timingDescription</code>: Unidirektionale Referenz, Kardinalität <code>0..1</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Reines statisches Entwurfs- und Konfigurations-Metamodell (Design-Time / Contract Phase); keine direkte Ausführung im Runtime-Stack (weder BSW-Calltree noch OS-Task-Dispatching).</li>\n<li><strong>Modellierungs- & Validierungslebenszyklus (Toolchain/System-Design):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Cluster-Definition:</em> Bereitstellung der <code>CpSoftwareCluster</code>- und <code>CpSoftwareClusterResource</code>-Modelle durch OEM/System-Integrator.</li>\n<li><em>Timing-Spezifikation:</em> Erstellung der <code>TimingDescription</code> (Definition von Timing-Events, Chain Constraints).</li>\n<li><em>Mapping & Kontraktbindung:</em> Instanziierung des <code>TDCpSoftwareClusterMappingSet</code>. Zuweisung eines Clusters als <code>+provider</code> (z. B. Basis-Cluster liefert Sensorwerte innerhalb 10 ms) und Zuweisung von 1..n Clustern als <code>+requestor</code> (Applikations-Cluster).</li>\n<li><em>Ressourcenallokation:</em> Mappen von spezifischen Timing-Budgets auf Shared Resources via <code>TDCpSoftwareClusterResourceMapping</code>.</li>\n<li><em>Metamodell-Postprocessing:</em> Toolchain (z. B. Timing-Analyzer, Schedule-Synthesizer) löst Varianten (<code>«atpVariation»</code>) und Dateisplits (<code>«atpSplitable»</code>) auf und prüft die Erfüllbarkeit (Schedulability Analysis) vor der ECU-Konfiguration.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Multi-Core- und Multi-Cluster-Entkopplung:</strong></li>\n<li>Erlaubt OEM und Zulieferern die Definition harter Timing-Verträge, ohne dass der Quellcode oder die interne Software-Component-Topologie (SWC) des Fremd-Clusters offengelegt werden muss (Black-Box-Contracting).</li>\n<li><strong>ARXML-Splitting (<code>«atpSplitable»</code>):</strong></li>\n<li>Entwickler müssen beachten, dass Mappings desselben <code>TDCpSoftwareClusterMappingSet</code> aus getrennten ARXML-Lieferungen zusammengeführt werden dürfen. Build-Pipelines und Validierungswerkzeuge müssen Fragment-Merges vor der Konsistenzprüfung unterstützen.</li>\n<li><strong>Variantenmanagement (<code>«atpVariation»</code>):</strong></li>\n<li>Timing-Anforderungen können an System-Conditions (Binding Times: System-Creation, Pre-Compile) gekoppelt sein; eine Timing-Verletzung darf nur für die tatsächlich evaluierte Systemkonfiguration berechnet werden.</li>\n<li><strong>Auswirkungen auf Stack/RTE/OS-Konfiguration:</strong></li>\n<li>Diese Mappings generieren keine direkten C-APIs, bilden jedoch die normative Eingangsbasis für den OS-Task-Scheduler, den Inter-Cluster-Kommunikationsstack (z. B. Non-RTE Cross-Cluster Communication / Memory Protection Boundaries) und Watchdog/Deadline-Monitoring.</li>\n<li>Eine Änderung an <code>+provider</code> oder <code>+requestor</code> erzwingt die Neuverifikation der Timing-Kette über Clustergrenzen hinweg (End-to-End-Latenzgarantien).</li>\n</ul>"}, {"id": "FIG-3445d37f2ff6c946", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> AUTOSAR-M2-Metamodell (UML-Klassendiagramm).</li>\n<li><strong>Technischer Zweck:</strong> Formale Definition des Mappings von Zeitbeschreibungen (<code>TimingDescription</code>) auf Classic-Platform-Software-Cluster (<code>CpSoftwareCluster</code>) sowie deren Ressourcen (<code>CpSoftwareClusterResource</code>) zur kontraktbasierten Schnittstellendefinition (SLA/Timing-Contracts) zwischen verteilten Entwicklungsparteien (OEM, Tier-1, Tier-2).</li>\n<li><strong>Funktionale Einordnung:</strong> Verankert in <code>AUTOSAR_TPS_TimingExtensions</code> (R20-11, Kap. 4.7.4; Anforderungen <code>RS_TIMEX_00025</code>, <code>TPS_TIMEX_00066</code>). Adressiert modulare, unabhängig updatebare Software-Cluster (SWCL) im Classic AUTOSAR, indem temporale Budgets, Latenzgrenzen und Ausführungsordnungen explizit als Provider- und Requestor-Rollen auf Clusterebene abgebildet werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Klassen & Generalisierungen</p>\n<ul class=\"fig-list\">\n<li><strong><code>TDCpSoftwareClusterMappingSet</code></strong> (Spezialisierung von <code>ARElement</code>): Top-Level-Container auf ARXML-Paketebene, bündelt alle clusterbezogenen Timing-Mappings eines Systems oder Teilsystems.</li>\n<li><strong><code>TDCpSoftwareClusterMapping</code></strong> (Spezialisierung von <code>Identifiable</code>): Assoziationsentität zur Verknüpfung einer Timing-Beschreibung mit Software-Clustern unter Berücksichtigung von Provider/Requestor-Rollen.</li>\n<li><strong><code>TDCpSoftwareClusterResourceMapping</code></strong> (Spezialisierung von <code>Identifiable</code>): Assoziationsentität zur Bindung einer Timing-Beschreibung an eine spezifische Software-Cluster-Ressource.</li>\n<li><strong><code>CpSoftwareCluster</code></strong> (Spezialisierung von <code>ARElement</code>):</li>\n<li>Repräsentiert die funktionale Einheit/Partition eines Classic-Platform-Software-Clusters.</li>\n<li>Attribut: <code>+ softwareClusterId: PositiveInteger [0..1]</code>.</li>\n<li><strong><code>CpSoftwareClusterResource</code></strong> (Spezialisierung von <code>Identifiable</code>): Repräsentiert eine konkrete Hardware-/Software-Ressource innerhalb eines Clusters.</li>\n<li><strong><code>TimingDescription</code></strong> (Spezialisierung von <code>Identifiable</code>): Abstrakter Zielcontainer der Timing Extensions für Timing-Ereignisse, Ketten und Randbedingungen.</li>\n</ul>\n<p class=\"fig-p\">#### Assoziationen, Kardinalitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>TDCpSoftwareClusterMappingSet</code> ➔ <code>TDCpSoftwareClusterMapping</code>:</strong> Komposition, Rolle <code>+tdCpSoftwareClusterToTdMapping</code>, Multiplizität <code>0..*</code>, Stereotypen <code>«atpVariation»</code>, <code>«atpSplitable»</code>.</li>\n<li><strong><code>TDCpSoftwareClusterMappingSet</code> ➔ <code>TDCpSoftwareClusterResourceMapping</code>:</strong> Komposition, Rolle <code>+tdCpSoftwareClusterResourceToTdMapping</code>, Multiplizität <code>0..*</code>, Stereotypen <code>«atpVariation»</code>, <code>«atpSplitable»</code>.</li>\n<li><strong><code>TDCpSoftwareClusterMapping</code> ➔ <code>CpSoftwareCluster</code>:</strong></li>\n<li>Rolle <code>+provider</code>: Unidirektionale Referenz, Multiplizität <code>0..1</code>.</li>\n<li>Rolle <code>+requestor</code>: Unidirektionale Referenz, Multiplizität <code>0..*</code>.</li>\n<li><strong><code>TDCpSoftwareClusterMapping</code> ➔ <code>TimingDescription</code>:</strong> Rolle <code>+timingDescription</code>, unidirektionale Referenz, Multiplizität <code>0..1</code>.</li>\n<li><strong><code>TDCpSoftwareClusterResourceMapping</code> ➔ <code>CpSoftwareClusterResource</code>:</strong> Rolle <code>+resource</code>, unidirektionale Referenz, Multiplizität <code>0..1</code>.</li>\n<li><strong><code>TDCpSoftwareClusterResourceMapping</code> ➔ <code>TimingDescription</code>:</strong> Rolle <code>+timingDescription</code>, unidirektionale Referenz, Multiplizität <code>0..1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Reines statisches Entwurfs- und Konfigurations-Metamodell (Design-Time / Contract Phase); keine direkte Ausführung im Runtime-Stack (weder BSW-Calltree noch OS-Task-Dispatching).</li>\n<li><strong>Modellierungs- & Validierungslebenszyklus (Toolchain/System-Design):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Cluster-Definition:</em> Bereitstellung der <code>CpSoftwareCluster</code>- und <code>CpSoftwareClusterResource</code>-Modelle durch OEM/System-Integrator.</li>\n<li><em>Timing-Spezifikation:</em> Erstellung der <code>TimingDescription</code> (Definition von Timing-Events, Chain Constraints).</li>\n<li><em>Mapping & Kontraktbindung:</em> Instanziierung des <code>TDCpSoftwareClusterMappingSet</code>. Zuweisung eines Clusters als <code>+provider</code> (z. B. Basis-Cluster liefert Sensorwerte innerhalb 10 ms) und Zuweisung von 1..n Clustern als <code>+requestor</code> (Applikations-Cluster).</li>\n<li><em>Ressourcenallokation:</em> Mappen von spezifischen Timing-Budgets auf Shared Resources via <code>TDCpSoftwareClusterResourceMapping</code>.</li>\n<li><em>Metamodell-Postprocessing:</em> Toolchain (z. B. Timing-Analyzer, Schedule-Synthesizer) löst Varianten (<code>«atpVariation»</code>) und Dateisplits (<code>«atpSplitable»</code>) auf und prüft die Erfüllbarkeit (Schedulability Analysis) vor der ECU-Konfiguration.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konformitätsanforderungen:</strong> Gemäß <code>TPS_TIMEX_00066</code> dient das Metamodell der formalen Vertragsbildung zwischen OEM und Zulieferern für Software-Cluster.</li>\n<li><strong>Modellierungsregeln:</strong></li>\n<li><code>CpSoftwareCluster</code> besitzt eine optionale numerische Kennung <code>softwareClusterId</code> vom Typ <code>PositiveInteger [0..1]</code>.</li>\n<li>Ein <code>TDCpSoftwareClusterMapping</code> darf maximal einen <code>provider</code> referenzieren (<code>0..1</code>), kann jedoch von mehreren <code>requestor</code>-Clustern referenziert werden (<code>0..*</code>).</li>\n<li>Beide Kompositionen unterliegen den Mechanismen <code>«atpVariation»</code> und <code>«atpSplitable»</code>.</li>\n<li><code>TimingDescription</code> sowie die Ressourcen müssen gültige AUTOSAR-Pfade besitzen (<code>Identifiable</code>).</li>\n</ul>"}, {"id": "FIG-b8632ad76a848328", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> AUTOSAR-M2-Metamodell (UML-Klassendiagramm).</li>\n<li><strong>Technischer Zweck:</strong> Formale Definition des Mappings von Zeitbeschreibungen (<code>TimingDescription</code>) auf Classic-Platform-Software-Cluster (<code>CpSoftwareCluster</code>) sowie deren Ressourcen (<code>CpSoftwareClusterResource</code>) zur kontraktbasierten Schnittstellendefinition (SLA/Timing-Contracts) zwischen verteilten Entwicklungsparteien (OEM, Tier-1, Tier-2).</li>\n<li><strong>Funktionale Einordnung:</strong> Verankert in <code>AUTOSAR_TPS_TimingExtensions</code> (R20-11, Kap. 4.7.4; Anforderungen <code>RS_TIMEX_00025</code>, <code>TPS_TIMEX_00066</code>). Adressiert modulare, unabhängig updatebare Software-Cluster (SWCL) im Classic AUTOSAR, indem temporale Budgets, Latenzgrenzen und Ausführungsordnungen explizit als Provider- und Requestor-Rollen auf Clusterebene abgebildet werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Klassen & Generalisierungen</p>\n<ul class=\"fig-list\">\n<li><strong><code>TDCpSoftwareClusterMappingSet</code></strong> (Spezialisierung von <code>ARElement</code>): Top-Level-Container auf ARXML-Paketebene, bündelt alle clusterbezogenen Timing-Mappings eines Systems oder Teilsystems.</li>\n<li><strong><code>TDCpSoftwareClusterMapping</code></strong> (Spezialisierung von <code>Identifiable</code>): Assoziationsentität zur Verknüpfung einer Timing-Beschreibung mit Software-Clustern unter Berücksichtigung von Provider/Requestor-Rollen.</li>\n<li><strong><code>TDCpSoftwareClusterResourceMapping</code></strong> (Spezialisierung von <code>Identifiable</code>): Assoziationsentität zur Bindung einer Timing-Beschreibung an eine spezifische Software-Cluster-Ressource.</li>\n<li><strong><code>CpSoftwareCluster</code></strong> (Spezialisierung von <code>ARElement</code>):</li>\n<li>Repräsentiert die funktionale Einheit/Partition eines Classic-Platform-Software-Clusters.</li>\n<li>Attribut: <code>+ softwareClusterId: PositiveInteger [0..1]</code>.</li>\n<li><strong><code>CpSoftwareClusterResource</code></strong> (Spezialisierung von <code>Identifiable</code>): Repräsentiert eine konkrete Hardware-/Software-Ressource innerhalb eines Clusters.</li>\n<li><strong><code>TimingDescription</code></strong> (Spezialisierung von <code>Identifiable</code>): Abstrakter Zielcontainer der Timing Extensions für Timing-Ereignisse, Ketten und Randbedingungen.</li>\n</ul>\n<p class=\"fig-p\">#### Assoziationen, Kardinalitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>TDCpSoftwareClusterMappingSet</code> ➔ <code>TDCpSoftwareClusterMapping</code>:</strong> Komposition, Rolle <code>+tdCpSoftwareClusterToTdMapping</code>, Multiplizität <code>0..*</code>, Stereotypen <code>«atpVariation»</code>, <code>«atpSplitable»</code>.</li>\n<li><strong><code>TDCpSoftwareClusterMappingSet</code> ➔ <code>TDCpSoftwareClusterResourceMapping</code>:</strong> Komposition, Rolle <code>+tdCpSoftwareClusterResourceToTdMapping</code>, Multiplizität <code>0..*</code>, Stereotypen <code>«atpVariation»</code>, <code>«atpSplitable»</code>.</li>\n<li><strong><code>TDCpSoftwareClusterMapping</code> ➔ <code>CpSoftwareCluster</code>:</strong></li>\n<li>Rolle <code>+provider</code>: Unidirektionale Referenz, Multiplizität <code>0..1</code>.</li>\n<li>Rolle <code>+requestor</code>: Unidirektionale Referenz, Multiplizität <code>0..*</code>.</li>\n<li><strong><code>TDCpSoftwareClusterMapping</code> ➔ <code>TimingDescription</code>:</strong> Rolle <code>+timingDescription</code>, unidirektionale Referenz, Multiplizität <code>0..1</code>.</li>\n<li><strong><code>TDCpSoftwareClusterResourceMapping</code> ➔ <code>CpSoftwareClusterResource</code>:</strong> Rolle <code>+resource</code>, unidirektionale Referenz, Multiplizität <code>0..1</code>.</li>\n<li><strong><code>TDCpSoftwareClusterResourceMapping</code> ➔ <code>TimingDescription</code>:</strong> Rolle <code>+timingDescription</code>, unidirektionale Referenz, Multiplizität <code>0..1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Reines statisches Entwurfs- und Konfigurations-Metamodell (Design-Time / Contract Phase); keine direkte Ausführung im Runtime-Stack (weder BSW-Calltree noch OS-Task-Dispatching).</li>\n<li><strong>Modellierungs- & Validierungslebenszyklus (Toolchain/System-Design):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Cluster-Definition:</em> Bereitstellung der <code>CpSoftwareCluster</code>- und <code>CpSoftwareClusterResource</code>-Modelle durch OEM/System-Integrator.</li>\n<li><em>Timing-Spezifikation:</em> Erstellung der <code>TimingDescription</code> (Definition von Timing-Events, Chain Constraints).</li>\n<li><em>Mapping & Kontraktbindung:</em> Instanziierung des <code>TDCpSoftwareClusterMappingSet</code>. Zuweisung eines Clusters als <code>+provider</code> (z. B. Basis-Cluster liefert Sensorwerte innerhalb 10 ms) und Zuweisung von 1..n Clustern als <code>+requestor</code> (Applikations-Cluster).</li>\n<li><em>Ressourcenallokation:</em> Mappen von spezifischen Timing-Budgets auf Shared Resources via <code>TDCpSoftwareClusterResourceMapping</code>.</li>\n<li><em>Metamodell-Postprocessing:</em> Toolchain (z. B. Timing-Analyzer, Schedule-Synthesizer) löst Varianten (<code>«atpVariation»</code>) und Dateisplits (<code>«atpSplitable»</code>) auf und prüft die Erfüllbarkeit (Schedulability Analysis) vor der ECU-Konfiguration.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konformitätsanforderungen:</strong> Gemäß <code>TPS_TIMEX_00066</code> dient das Metamodell der formalen Vertragsbildung zwischen OEM und Zulieferern für Software-Cluster.</li>\n<li><strong>Modellierungsregeln:</strong></li>\n<li><code>CpSoftwareCluster</code> besitzt eine optionale numerische Kennung <code>softwareClusterId</code> vom Typ <code>PositiveInteger [0..1]</code>.</li>\n<li>Ein <code>TDCpSoftwareClusterMapping</code> darf maximal einen <code>provider</code> referenzieren (<code>0..1</code>), kann jedoch von mehreren <code>requestor</code>-Clustern referenziert werden (<code>0..*</code>).</li>\n<li>Beide Kompositionen unterliegen den Mechanismen <code>«atpVariation»</code> und <code>«atpSplitable»</code>.</li>\n<li><code>TimingDescription</code> sowie die Ressourcen müssen gültige AUTOSAR-Pfade besitzen (<code>Identifiable</code>).</li>\n</ul>"}, {"id": "FIG-7cba0c799fb7302e", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> AUTOSAR-M2-Metamodell (UML-Klassendiagramm).</li>\n<li><strong>Technischer Zweck:</strong> Formale Definition des Mappings von Zeitbeschreibungen (<code>TimingDescription</code>) auf Classic-Platform-Software-Cluster (<code>CpSoftwareCluster</code>) sowie deren Ressourcen (<code>CpSoftwareClusterResource</code>) zur kontraktbasierten Schnittstellendefinition (SLA/Timing-Contracts) zwischen verteilten Entwicklungsparteien (OEM, Tier-1, Tier-2).</li>\n<li><strong>Funktionale Einordnung:</strong> Verankert in <code>AUTOSAR_TPS_TimingExtensions</code> (R20-11, Kap. 4.7.4; Anforderungen <code>RS_TIMEX_00025</code>, <code>TPS_TIMEX_00066</code>). Adressiert modulare, unabhängig updatebare Software-Cluster (SWCL) im Classic AUTOSAR, indem temporale Budgets, Latenzgrenzen und Ausführungsordnungen explizit als Provider- und Requestor-Rollen auf Clusterebene abgebildet werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Klassen & Generalisierungen</p>\n<ul class=\"fig-list\">\n<li><strong><code>TDCpSoftwareClusterMappingSet</code></strong> (Spezialisierung von <code>ARElement</code>): Top-Level-Container auf ARXML-Paketebene, bündelt alle clusterbezogenen Timing-Mappings eines Systems oder Teilsystems.</li>\n<li><strong><code>TDCpSoftwareClusterMapping</code></strong> (Spezialisierung von <code>Identifiable</code>): Assoziationsentität zur Verknüpfung einer Timing-Beschreibung mit Software-Clustern unter Berücksichtigung von Provider/Requestor-Rollen.</li>\n<li><strong><code>TDCpSoftwareClusterResourceMapping</code></strong> (Spezialisierung von <code>Identifiable</code>): Assoziationsentität zur Bindung einer Timing-Beschreibung an eine spezifische Software-Cluster-Ressource.</li>\n<li><strong><code>CpSoftwareCluster</code></strong> (Spezialisierung von <code>ARElement</code>):</li>\n<li>Repräsentiert die funktionale Einheit/Partition eines Classic-Platform-Software-Clusters.</li>\n<li>Attribut: <code>+ softwareClusterId: PositiveInteger [0..1]</code>.</li>\n<li><strong><code>CpSoftwareClusterResource</code></strong> (Spezialisierung von <code>Identifiable</code>): Repräsentiert eine konkrete Hardware-/Software-Ressource innerhalb eines Clusters.</li>\n<li><strong><code>TimingDescription</code></strong> (Spezialisierung von <code>Identifiable</code>): Abstrakter Zielcontainer der Timing Extensions für Timing-Ereignisse, Ketten und Randbedingungen.</li>\n</ul>\n<p class=\"fig-p\">#### Assoziationen, Kardinalitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>TDCpSoftwareClusterMappingSet</code> ➔ <code>TDCpSoftwareClusterMapping</code>:</strong> Komposition, Rolle <code>+tdCpSoftwareClusterToTdMapping</code>, Multiplizität <code>0..*</code>, Stereotypen <code>«atpVariation»</code>, <code>«atpSplitable»</code>.</li>\n<li><strong><code>TDCpSoftwareClusterMappingSet</code> ➔ <code>TDCpSoftwareClusterResourceMapping</code>:</strong> Komposition, Rolle <code>+tdCpSoftwareClusterResourceToTdMapping</code>, Multiplizität <code>0..*</code>, Stereotypen <code>«atpVariation»</code>, <code>«atpSplitable»</code>.</li>\n<li><strong><code>TDCpSoftwareClusterMapping</code> ➔ <code>CpSoftwareCluster</code>:</strong></li>\n<li>Rolle <code>+provider</code>: Unidirektionale Referenz, Multiplizität <code>0..1</code>.</li>\n<li>Rolle <code>+requestor</code>: Unidirektionale Referenz, Multiplizität <code>0..*</code>.</li>\n<li><strong><code>TDCpSoftwareClusterMapping</code> ➔ <code>TimingDescription</code>:</strong> Rolle <code>+timingDescription</code>, unidirektionale Referenz, Multiplizität <code>0..1</code>.</li>\n<li><strong><code>TDCpSoftwareClusterResourceMapping</code> ➔ <code>CpSoftwareClusterResource</code>:</strong> Rolle <code>+resource</code>, unidirektionale Referenz, Multiplizität <code>0..1</code>.</li>\n<li><strong><code>TDCpSoftwareClusterResourceMapping</code> ➔ <code>TimingDescription</code>:</strong> Rolle <code>+timingDescription</code>, unidirektionale Referenz, Multiplizität <code>0..1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Reines statisches Entwurfs- und Konfigurations-Metamodell (Design-Time / Contract Phase); keine direkte Ausführung im Runtime-Stack (weder BSW-Calltree noch OS-Task-Dispatching).</li>\n<li><strong>Modellierungs- & Validierungslebenszyklus (Toolchain/System-Design):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Cluster-Definition:</em> Bereitstellung der <code>CpSoftwareCluster</code>- und <code>CpSoftwareClusterResource</code>-Modelle durch OEM/System-Integrator.</li>\n<li><em>Timing-Spezifikation:</em> Erstellung der <code>TimingDescription</code> (Definition von Timing-Events, Chain Constraints).</li>\n<li><em>Mapping & Kontraktbindung:</em> Instanziierung des <code>TDCpSoftwareClusterMappingSet</code>. Zuweisung eines Clusters als <code>+provider</code> (z. B. Basis-Cluster liefert Sensorwerte innerhalb 10 ms) und Zuweisung von 1..n Clustern als <code>+requestor</code> (Applikations-Cluster).</li>\n<li><em>Ressourcenallokation:</em> Mappen von spezifischen Timing-Budgets auf Shared Resources via <code>TDCpSoftwareClusterResourceMapping</code>.</li>\n<li><em>Metamodell-Postprocessing:</em> Toolchain (z. B. Timing-Analyzer, Schedule-Synthesizer) löst Varianten (<code>«atpVariation»</code>) und Dateisplits (<code>«atpSplitable»</code>) auf und prüft die Erfüllbarkeit (Schedulability Analysis) vor der ECU-Konfiguration.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konformitätsanforderungen:</strong> Gemäß <code>TPS_TIMEX_00066</code> dient das Metamodell der formalen Vertragsbildung zwischen OEM und Zulieferern für Software-Cluster.</li>\n<li><strong>Modellierungsregeln:</strong></li>\n<li><code>CpSoftwareCluster</code> besitzt eine optionale numerische Kennung <code>softwareClusterId</code> vom Typ <code>PositiveInteger [0..1]</code>.</li>\n<li>Ein <code>TDCpSoftwareClusterMapping</code> darf maximal einen <code>provider</code> referenzieren (<code>0..1</code>), kann jedoch von mehreren <code>requestor</code>-Clustern referenziert werden (<code>0..*</code>).</li>\n<li>Beide Kompositionen unterliegen den Mechanismen <code>«atpVariation»</code> und <code>«atpSplitable»</code>.</li>\n<li><code>TimingDescription</code> sowie die Ressourcen müssen gültige AUTOSAR-Pfade besitzen (<code>Identifiable</code>).</li>\n</ul>"}, {"id": "FIG-c26296d00baa0653", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> AUTOSAR-M2-Metamodell (UML-Klassendiagramm).</li>\n<li><strong>Technischer Zweck:</strong> Formale Definition des Mappings von Zeitbeschreibungen (<code>TimingDescription</code>) auf Classic-Platform-Software-Cluster (<code>CpSoftwareCluster</code>) sowie deren Ressourcen (<code>CpSoftwareClusterResource</code>) zur kontraktbasierten Schnittstellendefinition (SLA/Timing-Contracts) zwischen verteilten Entwicklungsparteien (OEM, Tier-1, Tier-2).</li>\n<li><strong>Funktionale Einordnung:</strong> Verankert in <code>AUTOSAR_TPS_TimingExtensions</code> (R20-11, Kap. 4.7.4; Anforderungen <code>RS_TIMEX_00025</code>, <code>TPS_TIMEX_00066</code>). Adressiert modulare, unabhängig updatebare Software-Cluster (SWCL) im Classic AUTOSAR, indem temporale Budgets, Latenzgrenzen und Ausführungsordnungen explizit als Provider- und Requestor-Rollen auf Clusterebene abgebildet werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Klassen & Generalisierungen</p>\n<ul class=\"fig-list\">\n<li><strong><code>TDCpSoftwareClusterMappingSet</code></strong> (Spezialisierung von <code>ARElement</code>): Top-Level-Container auf ARXML-Paketebene, bündelt alle clusterbezogenen Timing-Mappings eines Systems oder Teilsystems.</li>\n<li><strong><code>TDCpSoftwareClusterMapping</code></strong> (Spezialisierung von <code>Identifiable</code>): Assoziationsentität zur Verknüpfung einer Timing-Beschreibung mit Software-Clustern unter Berücksichtigung von Provider/Requestor-Rollen.</li>\n<li><strong><code>TDCpSoftwareClusterResourceMapping</code></strong> (Spezialisierung von <code>Identifiable</code>): Assoziationsentität zur Bindung einer Timing-Beschreibung an eine spezifische Software-Cluster-Ressource.</li>\n<li><strong><code>CpSoftwareCluster</code></strong> (Spezialisierung von <code>ARElement</code>):</li>\n<li>Repräsentiert die funktionale Einheit/Partition eines Classic-Platform-Software-Clusters.</li>\n<li>Attribut: <code>+ softwareClusterId: PositiveInteger [0..1]</code>.</li>\n<li><strong><code>CpSoftwareClusterResource</code></strong> (Spezialisierung von <code>Identifiable</code>): Repräsentiert eine konkrete Hardware-/Software-Ressource innerhalb eines Clusters.</li>\n<li><strong><code>TimingDescription</code></strong> (Spezialisierung von <code>Identifiable</code>): Abstrakter Zielcontainer der Timing Extensions für Timing-Ereignisse, Ketten und Randbedingungen.</li>\n</ul>\n<p class=\"fig-p\">#### Assoziationen, Kardinalitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>TDCpSoftwareClusterMappingSet</code> ➔ <code>TDCpSoftwareClusterMapping</code>:</strong> Komposition, Rolle <code>+tdCpSoftwareClusterToTdMapping</code>, Multiplizität <code>0..*</code>, Stereotypen <code>«atpVariation»</code>, <code>«atpSplitable»</code>.</li>\n<li><strong><code>TDCpSoftwareClusterMappingSet</code> ➔ <code>TDCpSoftwareClusterResourceMapping</code>:</strong> Komposition, Rolle <code>+tdCpSoftwareClusterResourceToTdMapping</code>, Multiplizität <code>0..*</code>, Stereotypen <code>«atpVariation»</code>, <code>«atpSplitable»</code>.</li>\n<li><strong><code>TDCpSoftwareClusterMapping</code> ➔ <code>CpSoftwareCluster</code>:</strong></li>\n<li>Rolle <code>+provider</code>: Unidirektionale Referenz, Multiplizität <code>0..1</code>.</li>\n<li>Rolle <code>+requestor</code>: Unidirektionale Referenz, Multiplizität <code>0..*</code>.</li>\n<li><strong><code>TDCpSoftwareClusterMapping</code> ➔ <code>TimingDescription</code>:</strong> Rolle <code>+timingDescription</code>, unidirektionale Referenz, Multiplizität <code>0..1</code>.</li>\n<li><strong><code>TDCpSoftwareClusterResourceMapping</code> ➔ <code>CpSoftwareClusterResource</code>:</strong> Rolle <code>+resource</code>, unidirektionale Referenz, Multiplizität <code>0..1</code>.</li>\n<li><strong><code>TDCpSoftwareClusterResourceMapping</code> ➔ <code>TimingDescription</code>:</strong> Rolle <code>+timingDescription</code>, unidirektionale Referenz, Multiplizität <code>0..1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Reines statisches Entwurfs- und Konfigurations-Metamodell (Design-Time / Contract Phase); keine direkte Ausführung im Runtime-Stack (weder BSW-Calltree noch OS-Task-Dispatching).</li>\n<li><strong>Modellierungs- & Validierungslebenszyklus (Toolchain/System-Design):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Cluster-Definition:</em> Bereitstellung der <code>CpSoftwareCluster</code>- und <code>CpSoftwareClusterResource</code>-Modelle durch OEM/System-Integrator.</li>\n<li><em>Timing-Spezifikation:</em> Erstellung der <code>TimingDescription</code> (Definition von Timing-Events, Chain Constraints).</li>\n<li><em>Mapping & Kontraktbindung:</em> Instanziierung des <code>TDCpSoftwareClusterMappingSet</code>. Zuweisung eines Clusters als <code>+provider</code> (z. B. Basis-Cluster liefert Sensorwerte innerhalb 10 ms) und Zuweisung von 1..n Clustern als <code>+requestor</code> (Applikations-Cluster).</li>\n<li><em>Ressourcenallokation:</em> Mappen von spezifischen Timing-Budgets auf Shared Resources via <code>TDCpSoftwareClusterResourceMapping</code>.</li>\n<li><em>Metamodell-Postprocessing:</em> Toolchain (z. B. Timing-Analyzer, Schedule-Synthesizer) löst Varianten (<code>«atpVariation»</code>) und Dateisplits (<code>«atpSplitable»</code>) auf und prüft die Erfüllbarkeit (Schedulability Analysis) vor der ECU-Konfiguration.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konformitätsanforderungen:</strong> Gemäß <code>TPS_TIMEX_00066</code> dient das Metamodell der formalen Vertragsbildung zwischen OEM und Zulieferern für Software-Cluster.</li>\n<li><strong>Modellierungsregeln:</strong></li>\n<li><code>CpSoftwareCluster</code> besitzt eine optionale numerische Kennung <code>softwareClusterId</code> vom Typ <code>PositiveInteger [0..1]</code>.</li>\n<li>Ein <code>TDCpSoftwareClusterMapping</code> darf maximal einen <code>provider</code> referenzieren (<code>0..1</code>), kann jedoch von mehreren <code>requestor</code>-Clustern referenziert werden (<code>0..*</code>).</li>\n<li>Beide Kompositionen unterliegen den Mechanismen <code>«atpVariation»</code> und <code>«atpSplitable»</code>.</li>\n<li><code>TimingDescription</code> sowie die Ressourcen müssen gültige AUTOSAR-Pfade besitzen (<code>Identifiable</code>).</li>\n</ul>"}], "trans": [{"from": "FIG-ffa8c68d1caa60ff", "to": "FIG-3445d37f2ff6c946", "fr": "R20-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>CpSoftwareCluster</strong>: Attribut <code>+ softwareClusterId: PositiveInteger [0..1]</code> hinzugefügt; Paketpräfix <code>SoftwareCluster::</code> entfernt.</li>\n<li><strong>CpSoftwareClusterResource</strong>: Paketpräfix <code>SoftwareCluster::</code> entfernt; Position im Diagramm von rechts nach unten rechts verschoben; Assoziationslinie von <code>TDCpSoftwareClusterResourceMapping</code> verläuft nun nach unten statt nach rechts.</li>\n<li><strong>TimingDescription</strong>: Paketpräfix <code>TimingDescription::</code> entfernt.</li>\n</ul>"}, {"from": "FIG-3445d37f2ff6c946", "to": "FIG-b8632ad76a848328", "fr": "R22-11", "tr": "R23-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>CpSoftwareCluster</strong>: Zeilenumbruch beim Attributtyp angepasst (<code>PositiveInteger [0..1]</code> in separater Zeile).</li>\n<li><strong>TDCpSoftwareClusterResourceMapping</strong>: Beschriftungsanordnung der Assoziationsenden und Rollennamen entzerrt (<code>+resource 0..1</code> und Multiplizität <code>0..*</code> neu positioniert).</li>\n</ul>"}, {"from": "FIG-b8632ad76a848328", "to": "FIG-7cba0c799fb7302e", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7cba0c799fb7302e", "to": "FIG-c26296d00baa0653", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
